import {display,splitFilenames,groupData,subsetData,safeFilename,mergeGroups} from './core.js';
const paths={split:'M4 4h16v5H4z M8 9v5H4v6h6v-6H8 M16 9v5h-2v6h6v-6h-4',merge:'M4 4h6v6H4z M14 4h6v6h-6z M7 10v4h10v-4 M12 14v6 M7 20h10',lookup:'M10 17a7 7 0 1 1 5-2l5 5 M7 8h6 M7 11h4',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z m-4 9 3 3 5-6',help:'M9.1 9a3 3 0 1 1 5.8 1c-.6 1-2.9 1.5-2.9 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',upload:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M12 18v-7 m-3 3 3-3 3 3',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 12h8 M8 16h8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',spark:'m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8z',play:'m9 5 10 7-10 7z',download:'M12 3v12 m-4-4 4 4 4-4 M4 16v5h16v-5',close:'m6 6 12 12 M6 18 18 6',edit:'m15 5 4 4 M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z',grip:'M9 5h.01 M15 5h.01 M9 12h.01 M15 12h.01 M9 19h.01 M15 19h.01',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc=s=>display(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const modes={split:{name:'拆表',title:'按字段拆分表格',sub:'先预览分组，再重命名、合并或下载。',steps:['上传文件','选择字段','确认下载']},merge:{name:'合表',title:'将多张表合为一张',sub:'按表头名称对齐列，缺少的字段留空。',steps:['添加文件','调整顺序','预览下载']},lookup:{name:'Lookup',title:'从参照表补充数据',sub:'通过匹配列关联两张表，选择需要返回的字段。',steps:['选择表格','设置匹配','预览下载']}};
const demoData={headers:['员工编号','姓名','所属部门','城市'],rows:[['EB001','林晓','产品部','上海'],['EB002','陈一','设计部','杭州'],['EB003','王晴','市场部','北京'],['EB004','周远','产品部','上海'],['EB005','李可','设计部','深圳'],['EB006','张宁','市场部','杭州']]};
const state={mode:'split',split:{source:null,data:null,col:0,groups:[],selected:new Set(),history:[],groupView:null},merge:{files:[],result:null,filename:'合并结果',clean:true,totals:'auto'},lookup:{main:null,ref:null,mainData:null,refData:null,mainKey:0,refKey:0,returns:[],trim:true,ignoreCase:false,duplicate:'first',missing:'',result:null,duplicateReport:null,filter:'all',filename:'Lookup匹配结果'},dirty:{split:false,merge:false,lookup:false}};
let pickTarget='',busy=false,dragIndex=null,toastTimer,pendingIntent=null,worker=null,workerUrl=null,requestSerial=0,searchTimer;
const requests=new Map(),previews=new Map(),viewState=new Map();
const blankSplit=()=>({source:null,data:null,col:0,groups:[],selected:new Set(),history:[],groupView:null});
function toast(message,error=false){const e=$('#toast');e.textContent=message;e.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.className='',4500);}
function modal(html,kind=''){const dialog=$('#modal');dialog.classList.toggle('guide-modal',kind==='guide'||kind==='preview');dialog.classList.toggle('data-modal',kind==='preview');dialog.classList.toggle('confirm-modal',kind==='confirm');dialog.setAttribute('aria-label',kind==='guide'?'使用说明':kind==='preview'?'数据核对':'确认操作');$('#modal-content').innerHTML=html+(kind==='preview'?`<button class="icon-button preview-close" data-action="close-modal" aria-label="关闭数据预览">${icon('close')}</button>`:'');if(!dialog.open)dialog.showModal();}
function closeModal(){pendingIntent=null;$('#modal').close();}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function setProgress(label,percent=null){const el=$('#processing');el.hidden=false;el.innerHTML=`<span class="processing-spinner" aria-hidden="true"></span><span>${esc(label)}</span>${percent===null?'<span class="processing-note">后台处理中，可继续查看使用说明</span>':`<progress max="100" value="${percent}" aria-label="处理进度"></progress><span>${Math.floor(percent)}%</span>`}`;}
function getWorker(){if(worker)return worker;const embedded=$('#excelbomb-worker-source');if(embedded){workerUrl=URL.createObjectURL(new Blob([embedded.textContent],{type:'text/javascript'}));worker=new Worker(workerUrl);}else worker=new Worker(new URL('worker.js',location.href));worker.onmessage=({data})=>{if(data.progress){if(busy)setProgress(data.progress.label,data.progress.percent);return;}const pending=requests.get(data.id);if(!pending)return;requests.delete(data.id);if(data.error)pending.reject(new Error(data.error));else pending.resolve(data.result);};worker.onerror=e=>{for(const pending of requests.values())pending.reject(new Error('后台处理失败，请重新打开页面并选择文件。'));requests.clear();worker.terminate();worker=null;if(workerUrl)URL.revokeObjectURL(workerUrl);workerUrl=null;};return worker;}
function request(kind,payload,transfer=[]){return new Promise((resolve,reject)=>{const id=++requestSerial;requests.set(id,{resolve,reject});try{getWorker().postMessage({id,kind,payload},transfer);}catch(e){requests.delete(id);reject(e);}});}
async function run(label,fn){if(busy)throw new Error('正在处理文件，请稍候。');busy=true;$('#work-content').classList.add('processing-content');setProgress(label);try{return await fn();}finally{busy=false;$('#processing').hidden=true;$('#work-content').classList.remove('processing-content');}}
function dirty(mode=state.mode){state.dirty[mode]=true;}
function dispose(sources){const ids=sources.filter(Boolean).map(s=>s.id);if(ids.length)request('dispose',{ids}).catch(()=>{});}
function confirmReplace(title,fn){pendingIntent=fn;modal(`<h2>${esc(title)}</h2><p>当前文件、分组和预览结果将被替换。需要的结果请先下载。</p><div class="confirm-actions"><button class="button secondary" data-action="cancel-replace">保留当前内容</button><button class="button" data-action="confirm-replace">确认替换</button></div>`,'confirm');}
function hasRealContent(mode){if(mode==='split')return !!state.split.source&&!state.split.source.demo;if(mode==='merge')return state.merge.files.some(s=>!s.demo);return [state.lookup.main,state.lookup.ref].some(s=>s&&!s.demo);}
function steps(){const m=state.mode;const active=m==='split'?(state.split.groups.length?2:state.split.data?1:0):m==='merge'?(state.merge.result?2:state.merge.files.length?1:0):(state.lookup.result?2:state.lookup.main&&state.lookup.ref?1:0);$('#steps').innerHTML=modes[m].steps.map((label,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${i===active?'active':i<active?'done':''}"><i>${i<active?'✓':i+1}</i>${label}</span>`).join('');}
function render(){const scrollY=window.pageYOffset||0,sameMode=$('#work-content').dataset.mode===state.mode;const groupScroll=document.querySelector('.groups')?.scrollTop||0;const previousOptions=$('#lookup-options');if(previousOptions)state.lookup.optionsOpen=previousOptions.open;const m=state.mode;$('#tool-tabs').innerHTML=Object.entries(modes).map(([k,v])=>`<button id="tab-${k}" class="tool ${k===m?'active':''}" role="tab" aria-selected="${k===m}" aria-controls="tool-panel" tabindex="${k===m?'0':'-1'}" data-action="mode" data-mode="${k}">${icon(k)}<span>${v.name}</span></button>`).join('');$('#tool-panel').setAttribute('aria-labelledby',`tab-${m}`);$('#workspace-title').textContent=modes[m].title;$('#workspace-desc').textContent=modes[m].sub;steps();$('#work-content').innerHTML=m==='split'?renderSplit():m==='merge'?renderMerge():renderLookup();hydrate();const groupList=document.querySelector('.groups');if(groupList)groupList.scrollTop=groupScroll;$('#work-content').dataset.mode=m;if(sameMode&&scrollY)window.scrollTo(0,scrollY);}
function dropzone(target,compact=false){return `<button class="dropzone ${compact?'compact-zone':''}" data-upload="${target}" aria-label="${target==='lookup-main'?'上传主表':target==='lookup-ref'?'上传参照表':'上传 Excel 文件'}"><span class="upload-symbol">${icon('upload')}</span><strong>拖拽文件到这里，或 <em>点击上传</em></strong><small>XLSX / XLS / CSV · ≤ 30 MB</small></button>`;}
function numberControl(value,target){return `<div class="number-control"><button data-action="number" data-target="${target}" data-delta="-1" aria-label="表头行减一">−</button><input type="number" min="1" value="${value}" data-header="${target}" aria-label="表头所在行"><button data-action="number" data-target="${target}" data-delta="1" aria-label="表头行加一">+</button></div>`;}
function sheetOptions(source){return source.sheetNames.map(n=>`<option value="${esc(n)}" ${source.sheet===n?'selected':''}>${esc(n)}</option>`).join('');}
function sourceInfo(source,target){return `<div class="file-info">${icon('file')}<div><div class="file-name" title="${esc(source.name)}">${esc(source.name)}</div><div class="file-meta">${source.demo?'示例数据 · ':''}${source.sheetNames.length} 张工作表</div></div><button class="icon-button" data-upload="${target}" aria-label="更换文件">${icon('upload')}</button></div>`;}
function formatControl(source,target){return `<label class="check-option format-control"><input type="checkbox" data-preserve="${target}" ${source.preserveIdentifiers!==false?'checked':''}>编号按显示文本保留<span title="只将 00001 这类补零编号转为文本；普通金额仍保留为数字。">${icon('info')}</span></label>`;}
function sourceControls(source,target){return `<div class="source-settings"><div class="field"><label>工作表</label><select data-sheet="${target}" aria-label="选择工作表">${sheetOptions(source)}</select></div><div class="field"><label>表头行${headerHint()}</label>${numberControl(source.header,target)}</div></div>${formatControl(source,target)}`;}
function cellText(data,row,col){const value=data.rows[row][col],format=data.formats?.[row]?.[col];if(format&&typeof value!=='string'&&value!==''&&value!=null){try{return XLSX.utils.format_cell({t:value instanceof Date?'d':typeof value==='boolean'?'b':'n',v:value,z:format});}catch{}}return display(value);}
function table(data,key){
 previews.set(key,data);let view=viewState.get(key);
 if(!view){view={page:0,size:100,search:'',cache:null};viewState.set(key,view);}
 if(view.cache?.rows!==data.rows||view.cache?.search!==view.search){const needle=view.search.toLocaleLowerCase(),indices=[];data.rows.forEach((r,i)=>{if(!needle||r.some((v,j)=>cellText(data,i,j).toLocaleLowerCase().includes(needle)))indices.push(i);});view.cache={rows:data.rows,search:view.search,indices};}
 const indices=view.cache.indices,pages=Math.max(1,Math.ceil(indices.length/view.size));view.page=Math.min(view.page,pages-1);const offset=view.page*view.size,visible=indices.slice(offset,offset+view.size),expanded=['expanded-preview','group-preview','duplicate-preview','merge-cleaned'].includes(key);
 return `<div class="data-preview" data-preview-key="${key}"><div class="preview-tools"><label class="preview-search">${icon('lookup')}<input type="search" data-search="${key}" value="${esc(view.search)}" placeholder="搜索全部数据" aria-label="搜索预览数据"></label><select data-page-size="${key}" aria-label="每页行数">${[25,50,100,200,500].map(n=>`<option value="${n}" ${view.size===n?'selected':''}>${n} 行 / 页</option>`).join('')}</select>${!expanded?`<button class="button secondary small expand-preview-button" data-action="expand-preview" data-key="${key}">${icon('eye')}展开预览</button>`:''}</div><div class="table-wrap" tabindex="0" aria-label="数据表格，可横向和纵向滚动"><table><thead><tr><th title="原始行号">行</th>${data.headers.map(h=>`<th title="${esc(h)}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${visible.map(i=>`<tr><td>${data.rowNumbers?.[i]??i+1}</td>${data.headers.map((h,j)=>`<td title="${esc(cellText(data,i,j))}">${esc(cellText(data,i,j))||'<span class="blank-cell" aria-label="空白"></span>'}</td>`).join('')}</tr>`).join('')}${!visible.length?`<tr><td colspan="${data.headers.length+1}" class="no-results">${view.search?'没有找到符合条件的数据':'没有数据行'}</td></tr>`:''}</tbody></table></div><div class="preview-foot"><span>${view.search?`找到 ${indices.length} / `:'共 '}${data.rows.length.toLocaleString()} 行 · ${data.headers.length} 列</span><div class="pagination"><button class="icon-button" data-action="page" data-key="${key}" data-delta="-1" aria-label="上一页" ${!view.page?'disabled':''}>${icon('up')}</button><span>${view.page+1} / ${pages}</span><button class="icon-button" data-action="page" data-key="${key}" data-delta="1" aria-label="下一页" ${view.page>=pages-1?'disabled':''}>${icon('down')}</button></div></div></div>`;
}
function refreshTable(key){const node=document.querySelector(`[data-preview-key="${key}"]`);if(node&&previews.has(key))node.outerHTML=table(previews.get(key),key);}
function resetTable(key){viewState.delete(key);previews.delete(key);}
function renderSplit(){
 const s=state.split;
 const extractionButton=!s.data?`<button class="button full" data-action="extract" ${!s.source?'disabled':''}>${icon('spark')}提取表头</button>`:'';
 const fields=s.data?`${s.data.protectedIdentifiers&&s.source.preserveIdentifiers!==false?`<p class="field-help">已保留 ${s.data.protectedIdentifiers} 个编号的前导零</p>`:''}<div class="field"><div class="section-label">拆分字段<button class="text-button" data-action="extract">重新提取</button></div><div class="chips">${s.data.headers.map((h,i)=>`<button class="chip ${s.col===i?'selected':''}" data-action="split-col" data-col="${i}">${esc(h)}</button>`).join('')}</div></div><button class="button ${s.groups.length?'secondary ':''}full" data-action="split-preview">${icon('split')}${s.groups.length?'重新预览':'预览拆分结果'}</button>`:emptyPreview(s.source?'文件已就绪，下一步提取表头':'先选择需要拆分的文件',s.source?'确认左侧的工作表和表头行，再点击“提取表头”。':'上传文件后，选择表头所在行即可开始。','split');
 return `<div class="work-grid"><div class="config-panel split-config ${s.data?'has-fields':'awaiting-header'}"><div class="source-block"><h3 class="section-label">${icon('file')}源文件</h3>${s.source?sourceInfo(s.source,'split'):dropzone('split')}${s.source?sourceControls(s.source,'split'):`<div class="field inline"><label>表头所在行${headerHint()}</label>${numberControl(s.pendingHeader||1,'split')}</div>`}${extractionButton}</div><div class="setup-block">${fields}</div></div>${s.data?`<div class="preview-panel">${s.groups.length?renderGroups():`<div class="preview-top"><h3 class="section-label">${icon('eye')}数据预览</h3><span class="tag">${s.data.headers.length} 个字段</span></div>${table(s.data,'split-source')}`}</div>`:''}</div>`;
}
function snapshot(){const s=state.split;return {groups:s.groups.map(g=>({...g})),selected:[...s.selected]};}
function pushHistory(value=snapshot()){state.split.history.push(value);if(state.split.history.length>20)state.split.history.shift();}
function updateFinalNames(){const s=state.split,names=splitFilenames(s.groups),byId=new Map(s.groups.map((g,i)=>[g.id,names[i]]));document.querySelectorAll('[data-final-name]').forEach(el=>{const name=byId.get(el.dataset.finalName);if(name!==undefined){el.textContent=name;el.title=name;}});}
function renderGroups(){const s=state.split,names=splitFilenames(s.groups),needle=(s.groupSearch||'').toLocaleLowerCase(),visible=s.groups.map((g,i)=>({g,i})).filter(({g,i})=>!needle||g.name.toLocaleLowerCase().includes(needle)||names[i].toLocaleLowerCase().includes(needle));return `<div class="preview-top"><h3 class="section-label">${icon('split')}拆分结果<span class="tag">${s.groups.length} 个文件</span></h3><div class="preview-header-actions"><button class="text-button" data-action="undo-groups" ${!s.history.length?'disabled':''}>撤销</button><button class="text-button" data-action="split-reset">恢复分组</button></div></div><p class="preview-caption">全部分组直接展示。可改名、查看数据或选择多个分组合并；名称后自动附加条目数。</p><div class="group-controls"><div class="group-toolbar"><label class="check-option"><input type="checkbox" data-select-all ${s.selected.size===s.groups.length?'checked':''}>全选</label><span>${s.selected.size?`已选 ${s.selected.size} 项 · `:''}${needle?`显示 ${visible.length} / ${s.groups.length} 个分组`:`全部 ${s.groups.length} 个分组`} · 共 ${s.data.rows.length} 行</span></div><div class="group-actions">${s.groups.length>15?`<input type="search" data-group-search value="${esc(s.groupSearch||'')}" placeholder="搜索全部分组" aria-label="搜索分组">`:''}<button class="button secondary small" data-action="merge-groups" ${s.selected.size<2?'disabled':''}>${icon('merge')}合并选中分组</button><button class="button" data-action="download-split">${icon('download')}确认并下载 ZIP · ${s.groups.length} 个文件</button></div></div><div class="groups">${visible.map(({g,i})=>`<div class="group"><input type="checkbox" data-group-select="${g.id}" aria-label="选择 ${esc(g.name)}" ${s.selected.has(g.id)?'checked':''}>${icon('file')}<div class="group-data"><input type="text" value="${esc(g.name)}" data-original-name="${esc(g.name)}" data-group-name="${g.id}" aria-label="文件名"><small class="final-filename" data-final-name="${g.id}" title="${esc(names[i])}">${esc(names[i])}</small></div><button class="text-button group-view-button" data-action="view-group" data-group="${g.id}">查看</button><span class="group-count">${g.items.length} 条</span></div>`).join('')}${!visible.length?'<p class="field-help">没有找到符合条件的分组。</p>':''}</div>`;}
function outputBar(kind){const s=state[kind];return `<div class="result-bar"><input type="text" data-output-name="${kind}" id="${kind}-filename" value="${esc(s.filename)}" aria-label="导出文件名"><button class="button" data-action="download-${kind}">${icon('download')}下载 Excel</button></div><p class="output-name">最终文件名：<span data-output-final="${kind}">${esc(safeFilename(s.filename))}.xlsx</span></p>`;}
function mergeSummary(result){const report=result.mergeReport;if(!report)return '';const total=report.headersRemoved+report.footersRemoved+report.summariesRemoved;return `<div class="merge-summary"><div><strong>已合并 ${report.dataRows} 条明细</strong><p>${report.clean?`清理 ${report.headersRemoved} 行重复表头、${report.footersRemoved} 行页脚、${report.summariesRemoved} 行原表统计`:'按原始内容合并'}${report.summaryRowCount?' · 已重新生成一行总合计':''}${report.repairedDates?` · 已兼容 ${report.repairedDates} 个异常日期单元格`:''}</p>${report.sumColumns.length?`<p>求和字段：${report.sumColumns.map(esc).join('、')}</p>`:report.clean&&report.summariesRemoved?'<p>原表统计未能确认求和规则，输出保留完整明细，可查看原始统计。</p>':''}</div>${total?'<button class="text-button" data-action="view-merge-cleaned">查看清理明细</button>':''}</div>`;}
function renderMerge(){const s=state.merge;return `<div class="work-grid"><div class="config-panel"><div class="source-block"><h3 class="section-label">${icon('file')}源文件<span class="tag">可多选</span></h3>${dropzone('merge',s.files.length>0)}<div class="merge-clean-options"><label class="check-option"><input type="checkbox" data-merge-clean ${s.clean!==false?'checked':''}>自动清理重复表头和页脚</label><p class="field-help">自动识别表头，业务记录按文件顺序保留。</p><label for="merge-totals">原表合计 / 小计</label><select id="merge-totals" data-merge-totals ${s.clean===false?'disabled':''}><option value="auto" ${(s.totals||'auto')==='auto'?'selected':''}>核对后重算一行总合计</option><option value="none" ${s.totals==='none'?'selected':''}>只保留合并明细</option></select><p class="field-help">只对可确认求和的列汇总，编号、日期、单价、比例不相加。</p></div></div><div class="setup-block">${s.files.length?`<div class="merge-list">${s.files.map((f,i)=>`<div class="merge-file" draggable="true" data-drag-index="${i}"><div class="merge-file-top"><span class="drag-handle">${icon('grip')}</span><span class="order">${i+1}</span><span class="file-name" title="${esc(f.name)}">${esc(f.name)}</span><button class="icon-button" data-action="move-file" data-index="${i}" data-delta="-1" aria-label="上移" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-button" data-action="move-file" data-index="${i}" data-delta="1" aria-label="下移" ${i===s.files.length-1?'disabled':''}>${icon('down')}</button><button class="icon-button" data-action="remove-file" data-index="${i}" aria-label="移除文件">${icon('close')}</button></div><div class="file-config"><div><label>工作表</label><select data-sheet="merge-${i}" aria-label="${esc(f.name)} 工作表">${sheetOptions(f)}</select></div><div><label>表头行</label><input type="number" min="1" value="${f.header}" data-header="merge-${i}" aria-label="${esc(f.name)} 表头行"></div></div>${formatControl(f,`merge-${i}`)}<label class="check-option merge-auto-header"><input type="checkbox" data-merge-auto="${i}" ${f.autoHeader!==false?'checked':''}>自动识别表头<span class="file-meta">（手动改行号可指定）</span></label></div>`).join('')}</div><p class="field-help">拖动卡片调整顺序，也可使用上下移动按钮。</p>`:''}<button class="button full" data-action="merge-preview" ${s.files.length<2?'disabled':''}>${icon('merge')}合并并预览${s.files.length?` · ${s.files.length} 个文件`:''}</button></div></div><div class="preview-panel"><div class="preview-top"><h3 class="section-label">${icon('eye')}合并结果</h3>${s.result?`<span class="tag">${s.files.length} 个文件</span>`:''}</div>${s.result?`${mergeSummary(s.result)}${table(s.result,'merge-result')}${outputBar('merge')}`:emptyPreview('等待合并','添加至少两份文件，调整顺序后开始合并。','merge')}</div></div>`;}
function lookupSource(which,label){const source=state.lookup[which],target=`lookup-${which}`;return `<div><h3 class="section-label">${label}</h3>${source?`<div class="file-info"><div class="lookup-file-top"><div class="file-name" title="${esc(source.name)}">${esc(source.name)}</div><button class="icon-button" data-upload="${target}" aria-label="更换${label}">${icon('upload')}</button></div><select data-sheet="${target}" aria-label="${label}工作表">${sheetOptions(source)}</select><label class="lookup-header">表头行<input type="number" min="1" value="${source.header}" data-header="${target}" aria-label="${label}表头行"></label></div>${formatControl(source,target)}`:dropzone(target)}</div>`;}
function options(headers,value){return headers.map((h,i)=>`<option value="${i}" ${i===value?'selected':''}>${esc(h)}</option>`).join('');}
function lookupData(){const s=state.lookup;if(s.viewCache?.result===s.result&&s.viewCache.filter===s.filter)return s.viewCache.data;const indices=s.result.rows.map((r,i)=>i).filter(i=>s.filter==='all'||s.result.matchedRows[i]===(s.filter==='matched'));const data=s.filter==='all'?s.result:subsetData(s.result,indices);s.viewCache={result:s.result,filter:s.filter,data};return data;}
function renderLookup(){const s=state.lookup,main=s.mainData,ref=s.refData,duplicates=s.result?.duplicateData||s.duplicateReport;return `<div class="work-grid"><div class="config-panel lookup-config"><div class="source-block"><div class="lookup-uploads">${lookupSource('main','主表')}${lookupSource('ref','参照表')}</div>${s.sourceError?`<p class="notice">${esc(s.sourceError)}</p>`:''}</div><div class="setup-block">${main&&ref?`<div class="field"><div class="lookup-columns"><div class="field"><label>主表匹配列</label><select data-lookup="mainKey" aria-label="主表匹配列">${options(main.headers,s.mainKey)}</select></div><span class="link-symbol">${icon('link')}</span><div class="field"><label>参照表匹配列</label><select data-lookup="refKey" aria-label="参照表匹配列">${options(ref.headers,s.refKey)}</select></div></div></div><div class="field"><label>返回字段</label><div class="return-fields">${ref.headers.map((h,i)=>`<label class="check-option"><input type="checkbox" data-return="${i}" ${s.returns.includes(i)?'checked':''}>${esc(h)}</label>`).join('')}</div></div><details class="advanced" id="lookup-options" ${s.optionsOpen?'open':''}><summary>匹配选项<span>${s.ignoreCase?'忽略大小写':'精确匹配'}</span>${icon('down')}</summary><div class="field"><label>重复值处理</label><select data-lookup="duplicate" aria-label="重复值处理"><option value="first" ${s.duplicate==='first'?'selected':''}>取第一条</option><option value="last" ${s.duplicate==='last'?'selected':''}>取最后一条</option><option value="error" ${s.duplicate==='error'?'selected':''}>提示错误，暂停匹配</option></select></div><div class="field return-fields"><label class="check-option"><input type="checkbox" data-lookup="trim" ${s.trim?'checked':''}>忽略首尾空格</label><label class="check-option"><input type="checkbox" data-lookup="ignoreCase" ${s.ignoreCase?'checked':''}>忽略大小写</label></div><p class="field-help">未匹配的单元格保留为空；空白键不参与匹配。</p></details>`:''}<button class="button full" data-action="lookup-preview" ${!main||!ref?'disabled':''}>${icon('lookup')}匹配并预览</button></div></div><div class="preview-panel"><div class="preview-top"><h3 class="section-label">${icon('eye')}匹配结果</h3></div>${s.error?`<p class="notice">${esc(s.error)}</p>`:''}${s.result?`<div class="stats">${[['all',s.result.rows.length,'主表行数'],['matched',s.result.matched,'已匹配'],['unmatched',s.result.unmatched,'未匹配']].map(([filter,count,label])=>`<button class="stat ${filter==='unmatched'?'warn':''} ${s.filter===filter?'selected':''}" data-action="lookup-filter" data-filter="${filter}" aria-pressed="${s.filter===filter}"><strong>${count}</strong><span>${label}</span></button>`).join('')}</div>`:''}${duplicates?.rows.length?`<div class="diagnostic-bar"><span>${s.result?s.result.duplicates+' 条重复记录':'发现重复匹配值'}</span><button class="text-button" data-action="view-duplicates">查看重复值</button></div>`:''}${s.result?`${s.filter!=='all'?`<div class="filter-notice"><span>仅显示${s.filter==='unmatched'?'未匹配':'已匹配'}记录</span>${s.filter==='unmatched'?`<button class="text-button" data-action="download-unmatched">${icon('download')}导出未匹配</button>`:''}<button class="text-button" data-action="lookup-filter" data-filter="all">显示全部</button></div>`:''}${table(lookupData(),'lookup-result')}${outputBar('lookup')}`:emptyPreview('等待匹配','选择两张表，通过同一字段补充数据。','lookup')}</div></div>`;}
function findSource(target){if(target==='split')return state.split.source;if(target.startsWith('merge-'))return state.merge.files[Number(target.split('-')[1])];return state.lookup[target.slice(7)];}
function invalidate(target){if(target==='split'){Object.assign(state.split,{data:null,groups:[],selected:new Set(),history:[],groupView:null});resetTable('split-source');}else if(target.startsWith('merge')){state.merge.result=null;resetTable('merge-result');}else{Object.assign(state.lookup,{result:null,duplicateReport:null,error:null,mainKey:0,refKey:0,returns:[],viewCache:null});resetTable('lookup-result');}}
async function refreshLookupSources(){const s=state.lookup;s.sourceError=null;s.mainData=null;s.refData=null;for(const key of ['main','ref']){if(s[key]){try{s[`${key}Data`]=await request('extract',{source:s[key]});}catch(e){s.sourceError=e.message;}}}}
async function updateSource(target,field,value){const source=findSource(target);if(!source){if(target==='split')state.split.pendingHeader=value;render();return;}source[field]=value;if(target.startsWith('merge')){if(field==='header')source.autoHeader=false;if(field==='sheet'&&source.autoHeader!==false){const found=await request('merge-header',{source});source.header=found.header;}}invalidate(target);dirty(target==='split'?'split':target.startsWith('merge')?'merge':'lookup');if(target.startsWith('lookup'))await run('整理工作表',refreshLookupSources);render();}
async function readFiles(files,target,confirmed=false){if(busy)return;if(!files.length)return;if(target!=='merge'&&files.length>1)throw new Error('这里一次只能选择一个文件。');for(const file of files){if(!/\.(xlsx|xls|csv)$/i.test(file.name))throw new Error(`不支持「${file.name}」，请选择 Excel 或 CSV 文件。`);if(file.size>30*1024*1024)throw new Error('单个文件不能超过 30 MB。');}const old=target==='merge'?null:findSource(target);if(old&&!old.demo&&!confirmed){confirmReplace('替换当前文件？',()=>readFiles(files,target,true));return;}await run('读取文件',async()=>{const inputs=[];for(const file of files)inputs.push({name:file.name,buffer:await file.arrayBuffer()});const loaded=await request('read',{files:inputs,merge:target==='merge'},inputs.map(f=>f.buffer));if(target==='split'){loaded[0].header=state.split.pendingHeader||1;state.split={...blankSplit(),source:loaded[0]};resetTable('split-source');dispose([old]);}else if(target==='merge'){state.merge.files.push(...loaded);invalidate('merge');}else{state.lookup[target.slice(7)]=loaded[0];invalidate(target);dispose([old]);await refreshLookupSources();}dirty(target==='split'?'split':target==='merge'?'merge':'lookup');render();toast(`已读取 ${loaded.length} 个文件`);});}
async function sample(confirmed=false){const mode=state.mode;if(hasRealContent(mode)&&!confirmed){confirmReplace('用示例替换当前内容？',()=>sample(true));return;}await run('准备示例数据',async()=>{let definitions;if(mode==='split')definitions=[{name:'员工信息示例.xlsx',...demoData}];else if(mode==='merge')definitions=[{name:'第一季度员工.xlsx',headers:demoData.headers,rows:demoData.rows.slice(0,3)},{name:'第二季度员工.xlsx',headers:demoData.headers,rows:demoData.rows.slice(3)}];else definitions=[{name:'员工名单.xlsx',headers:demoData.headers.slice(0,2),rows:demoData.rows.map(r=>r.slice(0,2))},{name:'员工信息.xlsx',headers:demoData.headers,rows:demoData.rows.slice(0,5)}];const loaded=await request('sample',definitions);if(mode==='split'){dispose([state.split.source]);state.split={...blankSplit(),source:loaded[0]};resetTable('split-source');}else if(mode==='merge'){dispose(state.merge.files);state.merge={files:loaded,result:null,filename:'合并结果',clean:true,totals:'auto'};resetTable('merge-result');}else{dispose([state.lookup.main,state.lookup.ref]);Object.assign(state.lookup,{main:loaded[0],ref:loaded[1],mainKey:0,refKey:0,returns:[2,3],result:null,duplicateReport:null,error:null,missing:'',filter:'all',viewCache:null});await refreshLookupSources();resetTable('lookup-result');}state.dirty[mode]=false;render();toast('示例已就绪，可以直接体验完整流程。');});}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<20;i++){const el=document.createElement('i');el.className='confetti';el.style.left=`${25+Math.random()*65}%`;el.style.background=['#9ac77e','#1e8b59','#e3bd64','#b6cae4'][i%4];el.style.setProperty('--drift',`${Math.random()*200-100}px`);document.body.append(el);setTimeout(()=>el.remove(),2100);}}
async function downloadResult(data,name,markMode=null){await run('生成 Excel 文件',async()=>{const {buffer}=await request('xlsx',{data});saveBlob(new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`${safeFilename(name)}.xlsx`);if(markMode)state.dirty[markMode]=false;celebrate();toast('Excel 已生成，浏览器将开始下载。');});}
function moveFile(i,j){if(j<0||j>=state.merge.files.length)return;state.merge.files.splice(j,0,state.merge.files.splice(i,1)[0]);invalidate('merge');dirty('merge');render();}
async function action(name,el){switch(name){
 case 'mode':state.mode=el.dataset.mode;render();break;
 case 'sample':await sample();break;
 case 'help':guideMode=state.mode;modal(renderGuide(),'guide');break;
 case 'guide-tab':guideMode=el.dataset.guide;$('#modal-content').innerHTML=renderGuide();$('#guide-'+guideMode).focus();break;
 case 'cancel-replace':case 'close-guide':case 'close-modal':closeModal();break;
 case 'confirm-replace':{const fn=pendingIntent;pendingIntent=null;$('#modal').close();if(fn)await fn();break;}
 case 'extract':await run('提取表头',async()=>{const s=state.split;s.data=await request('extract',{source:s.source});s.col=0;s.groups=[];s.history=[];s.selected.clear();resetTable('split-source');dirty('split');render();toast(`成功提取 ${s.data.headers.length} 个字段`);});break;
 case 'number':{const target=el.dataset.target,source=findSource(target),value=Math.max(1,Number(source?.header||state.split.pendingHeader||1)+Number(el.dataset.delta));await updateSource(target,'header',value);break;}
 case 'split-col':state.split.col=Number(el.dataset.col);state.split.groups=[];state.split.history=[];state.split.selected.clear();dirty('split');render();break;
 case 'split-preview':case 'split-reset':await run('生成分组预览',async()=>{const s=state.split;const result=await request('split',{source:s.source,column:s.col});if(!result.groups.length)throw new Error('表格没有数据行，无法拆分。');if(s.groups.length)pushHistory();s.data=result.data;s.groups=result.groups;s.groupSearch='';s.selected.clear();dirty('split');render();});break;
 case 'undo-groups':{const s=state.split,last=s.history.pop();if(last){s.groups=last.groups;s.selected=new Set(last.selected);dirty('split');render();toast('已撤销上一步分组操作。');}break;}
 case 'expand-preview':{const key=el.dataset.key,data=previews.get(key);if(!data)break;resetTable('expanded-preview');viewState.set('expanded-preview',{...viewState.get(key),cache:null});modal(`<h2>数据预览</h2><p class="preview-caption">共 ${data.rows.length.toLocaleString()} 行 · ${data.headers.length} 列，行号对应原始工作表。</p>${table(data,'expanded-preview')}`,'preview');break;}
 case 'view-group':{const s=state.split,g=s.groups.find(g=>g.id===el.dataset.group);resetTable('group-preview');modal(`<h2>${esc(splitFilenames(s.groups)[s.groups.indexOf(g)])}</h2><p class="preview-caption">共 ${g.items.length} 条，行号对应原始工作表。</p>${table(groupData(s.data,g),'group-preview')}`,'preview');break;}
 case 'merge-groups':{const s=state.split;modal(`<h2>合并选中的 ${s.selected.size} 个分组</h2><p>保留原表的数据顺序，文件名会自动附加合并后的条目数。</p><label class="field"><span>合并后的名称</span><input id="group-merge-name" type="text" value="合并分组" maxlength="85"></label><button class="button" data-action="confirm-merge-groups">确认合并</button>`);break;}
 case 'confirm-merge-groups':{const s=state.split;pushHistory();s.groups=mergeGroups(s.groups,[...s.selected],$('#group-merge-name').value);s.selected.clear();closeModal();dirty('split');render();toast('分组已合并，可随时撤销。');break;}
 case 'download-split':{const s=state.split;if(!s.groups.length)return;if(s.groups.some(g=>!g.name.trim()))throw new Error('请为所有分组填写文件名。');await run('生成拆分文件',async()=>{const {buffer}=await request('zip',{data:s.data,groups:s.groups});saveBlob(new Blob([buffer],{type:'application/zip'}),'ExcelBomb_拆分结果.zip');state.dirty.split=false;celebrate();toast(`已生成 ${s.groups.length} 个 Excel 文件`);});break;}
 case 'move-file':moveFile(Number(el.dataset.index),Number(el.dataset.index)+Number(el.dataset.delta));break;
 case 'remove-file':dispose(state.merge.files.splice(Number(el.dataset.index),1));invalidate('merge');dirty('merge');render();break;
 case 'merge-preview':await run('合并表格',async()=>{state.merge.result=await request('merge',{sources:state.merge.files,options:{clean:state.merge.clean!==false,totals:state.merge.totals||'auto'}});resetTable('merge-result');dirty('merge');render();toast('合并完成，请预览后下载。');});break;
 case 'view-merge-cleaned':{const data=state.merge.result?.mergeReport?.removedData;if(!data)return;resetTable('merge-cleaned');modal(`<h2>合表清理明细</h2><p class="preview-caption">列出自动移除的结构行，原始文件没有被修改。</p>${table(data,'merge-cleaned')}`,'preview');break;}
 case 'download-merge':await downloadResult(state.merge.result,state.merge.filename,'merge');break;
 case 'lookup-preview':await run('匹配数据',async()=>{const s=state.lookup,response=await request('lookup',{main:s.main,ref:s.ref,options:{mainKey:s.mainKey,refKey:s.refKey,returns:s.returns,trim:s.trim,ignoreCase:s.ignoreCase,duplicate:s.duplicate,missing:''}});Object.assign(s,{mainData:response.main,refData:response.ref,result:response.result||null,duplicateReport:response.duplicateData||null,error:response.error||null,filter:'all',viewCache:null});resetTable('lookup-result');dirty('lookup');render();toast(response.error||`匹配完成：${s.result.matched} 行成功，${s.result.unmatched} 行未匹配`,!!response.error);});break;
 case 'lookup-filter':state.lookup.filter=el.dataset.filter;resetTable('lookup-result');render();break;
 case 'view-duplicates':{const data=state.lookup.result?.duplicateData||state.lookup.duplicateReport;resetTable('duplicate-preview');modal(`<h2>重复匹配记录</h2><p class="preview-caption">包含同一匹配值的全部参照记录，行号用于回到原表核对。</p>${table(data,'duplicate-preview')}<button class="button secondary" data-action="download-duplicates">${icon('download')}导出重复记录</button>`,'preview');break;}
 case 'download-duplicates':await downloadResult(state.lookup.result?.duplicateData||state.lookup.duplicateReport,'Lookup_重复记录');break;
 case 'download-unmatched':{const s=state.lookup;await downloadResult(subsetData(s.result,s.result.matchedRows.flatMap((found,i)=>found?[]:[i])),'Lookup_未匹配记录');break;}
 case 'download-lookup':await downloadResult(state.lookup.result,state.lookup.filename,'lookup');break;
 case 'page':{const view=viewState.get(el.dataset.key);view.page+=Number(el.dataset.delta);refreshTable(el.dataset.key);break;}
}}
document.addEventListener('click',async e=>{const upload=e.target.closest('[data-upload]'),el=e.target.closest('[data-action]');const actionName=el?.dataset.action;if(busy&&(upload||el)&&!['help','guide-tab','close-guide','close-modal'].includes(actionName))return;try{if(upload){pickTarget=upload.dataset.upload;$('#file-picker').multiple=pickTarget==='merge';$('#file-picker').value='';$('#file-picker').click();return;}if(el&&!el.disabled)await action(actionName,el);}catch(error){toast(error.message,true);}});
$('#file-picker').addEventListener('change',e=>{if(e.target.files.length)readFiles([...e.target.files],pickTarget).catch(e=>toast(e.message,true));});
document.addEventListener('change',async e=>{const el=e.target;if(busy)return;try{
 if(el.hasAttribute('data-merge-clean')){state.merge.clean=el.checked;invalidate('merge');dirty('merge');render();}
 else if(el.hasAttribute('data-merge-totals')){state.merge.totals=el.value;invalidate('merge');dirty('merge');render();}
 else if(el.hasAttribute('data-merge-auto')){const source=state.merge.files[Number(el.dataset.mergeAuto)];source.autoHeader=el.checked;if(el.checked){const found=await request('merge-header',{source});source.header=found.header;}invalidate('merge');dirty('merge');render();}
 else if(el.dataset.sheet)await updateSource(el.dataset.sheet,'sheet',el.value);
 else if(el.dataset.header){const value=Number(el.value);if(!Number.isInteger(value)||value<1){el.value=findSource(el.dataset.header)?.header||1;throw new Error('表头行必须是大于零的整数。');}await updateSource(el.dataset.header,'header',value);}
 else if(el.dataset.preserve)await updateSource(el.dataset.preserve,'preserveIdentifiers',el.checked);
 else if(el.hasAttribute('data-group-select')){if(el.checked)state.split.selected.add(el.dataset.groupSelect);else state.split.selected.delete(el.dataset.groupSelect);render();}
 else if(el.hasAttribute('data-select-all')){state.split.selected=new Set(el.checked?state.split.groups.map(g=>g.id):[]);render();}
 else if(el.dataset.groupName){if(el.value!==el.dataset.originalName){const before=snapshot();before.groups.find(g=>g.id===el.dataset.groupName).name=el.dataset.originalName;pushHistory(before);el.dataset.originalName=el.value;dirty('split');const undo=document.querySelector('[data-action=undo-groups]');if(undo)undo.disabled=false;}}
 else if(el.dataset.lookup){const key=el.dataset.lookup;state.lookup[key]=el.type==='checkbox'?el.checked:key.endsWith('Key')?Number(el.value):el.value;state.lookup.result=null;state.lookup.duplicateReport=null;state.lookup.error=null;state.lookup.viewCache=null;dirty('lookup');render();}
 else if(el.hasAttribute('data-return')){const index=Number(el.dataset.return);if(el.checked)state.lookup.returns.push(index);else state.lookup.returns=state.lookup.returns.filter(i=>i!==index);state.lookup.returns.sort((a,b)=>a-b);state.lookup.result=null;state.lookup.duplicateReport=null;state.lookup.error=null;dirty('lookup');render();}
 else if(el.dataset.pageSize){const view=viewState.get(el.dataset.pageSize);view.size=Number(el.value);view.page=0;refreshTable(el.dataset.pageSize);}
 }catch(error){toast(error.message,true);}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.groupName){state.split.groups.find(g=>g.id===el.dataset.groupName).name=el.value;dirty('split');updateFinalNames();}else if(el.dataset.outputName){state[el.dataset.outputName].filename=el.value;dirty(el.dataset.outputName);const preview=document.querySelector(`[data-output-final="${el.dataset.outputName}"]`);if(preview)preview.textContent=`${safeFilename(el.value)}.xlsx`;}else if(el.hasAttribute('data-group-search')){clearTimeout(searchTimer);const text=el.value,start=el.selectionStart;searchTimer=setTimeout(()=>{state.split.groupSearch=text;render();const input=document.querySelector('[data-group-search]');if(input){input.focus();input.setSelectionRange(start,start);}},180);}else if(el.dataset.search){clearTimeout(searchTimer);const key=el.dataset.search,text=el.value,start=el.selectionStart;searchTimer=setTimeout(()=>{const view=viewState.get(key);view.search=text;view.page=0;refreshTable(key);const input=document.querySelector(`[data-search="${key}"]`);if(input){input.focus();input.setSelectionRange(start,start);}},180);}});
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag-index]');if(!row||busy)return;if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName)){e.preventDefault();return;}dragIndex=Number(row.dataset.dragIndex);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIndex));row.classList.add('dragging');});
document.addEventListener('dragend',()=>{dragIndex=null;document.querySelectorAll('.dragging,.dragover').forEach(el=>el.classList.remove('dragging','dragover'));});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-upload],[data-drag-index]');if(zone&&!busy){e.preventDefault();zone.classList.add('dragover');}});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-upload],[data-drag-index]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('dragover');});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-upload],[data-drag-index]');if(!zone)return;e.preventDefault();zone.classList.remove('dragover');if(busy)return;if(e.dataTransfer.files.length&&zone.dataset.upload){readFiles([...e.dataTransfer.files],zone.dataset.upload).catch(e=>toast(e.message,true));return;}if(zone.hasAttribute('data-drag-index')&&dragIndex!==null){moveFile(dragIndex,Number(zone.dataset.dragIndex));dragIndex=null;}});
document.addEventListener('keydown',e=>{if(e.key==='?'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open)action('help');const tab=e.target.closest('[role="tab"]');if(busy||!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(modes),i=keys.indexOf(state.mode);state.mode=e.key==='Home'?keys[0]:e.key==='End'?keys.at(-1):keys[(i+(e.key==='ArrowLeft'?-1:1)+keys.length)%keys.length];render();$(`#tab-${state.mode}`).focus();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>pendingIntent=null);
$('#modal').addEventListener('close',()=>{resetTable('group-preview');resetTable('duplicate-preview');resetTable('expanded-preview');resetTable('merge-cleaned');$('#modal-content').innerHTML='';});
window.addEventListener('beforeunload',e=>{if(busy||Object.values(state.dirty).some(Boolean)){e.preventDefault();e.returnValue='';}});
function headerHint(){return `<span class="label-hint" title="表头上方的说明行不会导出" aria-label="表头上方的说明行不会导出">${icon('info')}</span>`;}
function emptyPreview(title,description,kind){return `<div class="empty-preview"><div class="empty-art" aria-hidden="true"><div class="empty-paper">${icon(kind)}</div><span class="empty-star">✧</span></div><strong class="empty-title">${title}</strong><p>${description}</p></div>`;}

let guideMode='split';
function guideTable(headers,rows,highlight=-1){return `<div class="guide-grid" style="--guide-columns:${headers.length}">${headers.map((h,i)=>`<span class="mini-header ${i===highlight?'mini-highlight':''}">${h}</span>`).join('')}${rows.map(r=>r.map((v,i)=>`<span class="${i===highlight?'mini-highlight':''}">${v}</span>`).join('')).join('')}</div>`;}
function guideFile(name,kind='file',extra=''){return `<div class="mini-file">${icon(kind)}<span>${name}</span>${extra?`<small>${extra}</small>`:''}</div>`;}
function guideStep(number,title,visual,text){return `<article class="guide-step"><div class="guide-visual" aria-label="${title}操作示意">${visual}</div><div class="guide-step-heading"><span>${number}</span><h3>${title}</h3></div><p>${text}</p></article>`;}
function renderGuide(){
  const content={
    split:{name:'拆表',intro:'将一张大表，按某个字段分成多个 Excel。',steps:[
      ['上传并识别表头',`${guideTable(['姓名','部门'],[['林晓','研发部'],['陈一','销售部']])}<div class="mini-setting"><span>表头所在行</span><b>1</b></div>`,'上传文件，选择工作表和表头所在行，点击「提取表头」。'],
      ['选择拆分依据',`<div class="mini-chips"><span>姓名</span><span class="chosen">${icon('check')}部门</span><span>城市</span></div>${guideTable(['姓名','部门'],[['林晓','研发部'],['陈一','销售部']],1)}`,'例如选择「部门」，再点击「预览拆分结果」，相同部门会归入同一组。'],
      ['整理分组并下载',`${guideFile('研发部-1.xlsx','file','1 行')}${guideFile('销售部-1.xlsx','file','1 行')}<div class="mini-action">${icon('download')}下载 ZIP</div>`,'可查看每组全部数据、修改名称或合并分组，并支持撤销。下载的文件名自动带上条目数。']
    ],tip:'表头不在第一行？将“表头所在行”改为实际行号，表头上方的说明行不会导出。'},
    merge:{name:'合表',intro:'将多份文件的数据，按你指定的顺序追加到一张表。',steps:[
      ['添加多个文件',`${guideFile('11月订单.xlsx','file')}${guideFile('12月订单.xlsx','file')}<div class="mini-setting"><span>工作表</span><b>订单</b><span>表头</span><b>自动识别</b></div>`,'一次选择多份文件，默认自动识别表头。每份文件可选择工作表，也可手动修改表头行号。'],
      ['调整合并顺序',`<div class="mini-sort"><div>${icon('grip')}<b>1</b><span>12月订单.xlsx</span></div><div>${icon('grip')}<b>2</b><span>11月订单.xlsx</span></div></div><div class="mini-drag-hint">${icon('up')}${icon('down')}拖动卡片或使用上下按钮</div>`,'按住卡片拖动，或用上下按钮排序。排在前面的文件，数据也会出现在前面。'],
      ['预览合并结果',`${guideTable(['编号','月份','金额'],[['ORD02','12月','100'],['ORD01','11月','80'],['合计','','180']])}<div class="mini-action">${icon('download')}下载 Excel</div>`,'点击「合并并预览」，自动清理分页结构和原表统计，对可确认求和的字段重算总合计。可查看清理明细，核对后直接下载 Excel。']
    ],tip:'默认清理重复表头、页脚和原表统计，确认求和的列重算总合计；业务明细不会按内容去重。'},
    lookup:{name:'Lookup',intro:'通过共同字段，从参照表中找到数据并补充到主表。',steps:[
      ['选择主表和参照表',`<div class="mini-table-label">主表 · 需要补充数据</div>${guideTable(['员工编号','姓名'],[['EB001','林晓']])}<div class="mini-table-label">参照表 · 提供数据</div>${guideTable(['员工编号','部门'],[['EB001','研发部']])}`,'主表是需要补全的表，参照表提供要查找的数据。分别选择工作表和表头行。'],
      ['连接字段，选择返回值',`<div class="mini-link"><div><span>主表匹配列</span><b>员工编号</b></div>${icon('link')}<div><span>参照表匹配列</span><b>员工编号</b></div></div><div class="mini-return">返回字段<span>${icon('check')}部门</span></div>`,'两侧都选择能识别同一条记录的字段，如「员工编号」；再勾选要返回的字段，可多选。'],
      ['检查匹配结果',`${guideTable(['员工编号','姓名','部门'],[['EB001','林晓','研发部']],2)}<div class="mini-metrics"><span><b>1</b>已匹配</span><span><b>0</b>未匹配</span></div>`,'点击「匹配并预览」。返回字段加在主表右侧，主表行数保持不变，可点击统计筛选已匹配或未匹配记录，重复值也能展开查看。核对后下载。']
    ],tip:'展开“匹配选项”，可设置重复值处理、是否忽略首尾空格和英文字母大小写。未匹配的单元格保持空白。'}
  };
  const guide=content[guideMode];
  return `<div class="guide-heading"><div><h2 id="guide-title">使用说明</h2><p>选一个工具，跟着三个步骤完成操作。</p></div><button class="icon-button" data-action="close-guide" aria-label="关闭使用说明">${icon('close')}</button></div><nav class="guide-tabs" aria-label="使用指南分类">${Object.entries(content).map(([key,value])=>`<button id="guide-${key}" class="${key===guideMode?'active':''}" aria-pressed="${key===guideMode}" data-action="guide-tab" data-guide="${key}">${icon(key)}${value.name}</button>`).join('')}</nav><section class="guide-section" aria-labelledby="guide-${guideMode}"><p class="guide-intro">${guide.intro}</p><div class="guide-steps">${guide.steps.map((step,i)=>guideStep(i+1,...step)).join('')}</div><p class="guide-tip">${icon('info')}<span>${guide.tip}</span></p></section><details class="guide-data"><summary>文件格式与数据说明${icon('down')}</summary><div><p><strong>支持的文件：</strong>XLSX、XLS、CSV，统一导出 XLSX；拆表文件按“名称-条目数.xlsx”命名。单文件最多 30 MB，每张输入表最多 20 万条实际数据、1000 列，实际数据区域最多 500 万个单元格。</p><p><strong>本地处理：</strong>文件不会上传。刷新或关闭页面会清空当前操作。有未下载的修改时，浏览器会提醒。可双击文件夹中的“启动 ExcelBomb.command”打开本地工作台。</p><p><strong>导出内容：</strong>保留数据值，保留数字和日期的单元格格式，不保留其他原始样式、图表、宏或合并单元格。补零编号默认按显示文本保留，可在文件下方取消。公式使用文件已有的计算值，没有缓存结果的公式可能为空。自动忽略空白行和外围空白列，按实际数据判断容量；空白或重复表头会自动补全为唯一字段名。</p><p><strong>Lookup 规则：</strong>空白键不参与匹配。数字 123 与文本“123”可匹配，文本“00123”单独匹配。</p></div></details><p class="guide-practice">初次使用，可回到工作台点击「试试示例」练习。</p>`;
}

render();
